#include <fmt/core.h>

template<typename From, typename To>
struct VarConverter {
    static To Convert(const From& value) {
        return static_cast<To>(value);
    }
};

// Specialization for numeric to string conversion
template<typename T>
struct VarConverter<T, std::string> {
    static std::string Convert(const T& value) {
        return fmt::format("{}", value);
    }
};

// Specialization for string to numeric conversion
template<typename To>
struct VarConverter<std::string, To> {
    static To Convert(const std::string& value) {
        try {
            return static_cast<To>(std::stoi(value));
        } catch (const std::exception& e) {
            throw std::invalid_argument(fmt::format("Failed to convert string '{}' to type {}", value, typeid(To).name()));
        }
    }
};

// Specialization for string to list conversion
template<typename T>
struct VarConverter<std::string, std::list<T>> {
    static std::list<T> Convert(const std::string& value) {
        // Implementation would parse the string into a list of T
        throw std::invalid_argument("String to list conversion not implemented");
    }
};

