#pragma once
#include <string>
#include <memory>
#include <shared_mutex>
#include "VarConverter.hpp"

class VarBase {
public:
    virtual ~VarBase() = default;
    virtual std::string Name() const = 0;
    virtual std::string Description() const = 0;
    virtual std::string ToString() const = 0;
    virtual void FromString(const std::string& value) = 0;
};

template<typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var : public VarBase {
public:
    explicit Var(const std::string& name, const std::string& description = "")
        : name_(name), description_(description) {}

    T GetValue() const {
        std::shared_lock lock(mutex_);
        return value_;
    }

    void SetValue(const T& newValue) {
        {
            std::unique_lock lock(mutex_);
            if (value_ == newValue) {
                return;
            }
            value_ = newValue;
        }
        NotifyListeners();
    }

    std::string TypeName() const {
        return typeid(T).name();
    }

    void AddListener(std::shared_ptr<void> listener) {
        std::unique_lock lock(mutex_);
        listeners_.push_back(listener);
    }

    void RemoveListener(std::shared_ptr<void> listener) {
        std::unique_lock lock(mutex_);
        auto it = std::find(listeners_.begin(), listeners_.end(), listener);
        if (it != listeners_.end()) {
            listeners_.erase(it);
        }
    }

    void ClearListeners() {
        std::unique_lock lock(mutex_);
        listeners_.clear();
    }

    std::string Name() const override {
        return name_;
    }

    std::string Description() const override {
        return description_;
    }

    std::string ToString() const override {
        return ToStr::Convert(value_);
    }

    void FromString(const std::string& value) override {
        try {
            T newValue = FromStr::Convert(value);
            SetValue(newValue);
        } catch (const std::exception& e) {
            throw std::invalid_argument(fmt::format("Failed to convert string '{}' to type {}", value, TypeName()));
        }
    }

private:
    void NotifyListeners() {
        // Implementation would notify all listeners
    }

    mutable std::shared_mutex mutex_;
    T value_;
    std::string name_;
    std::string description_;
    std::vector<std::shared_ptr<void>> listeners_;
};
